package com.contentplatform.backend.database.repository

import com.contentplatform.backend.domain.common.PublicId
import com.contentplatform.backend.repository.*
import org.springframework.jdbc.core.JdbcTemplate

class ForumJdbcRepository(private val jdbc: JdbcTemplate):ForumRepository {
 override fun listBoards(userId:PublicId?):List<ForumBoard>{val sql=boardSql(withFollowing=userId!=null);val rows=if(userId==null)jdbc.query(sql,{rs,_->boardRow(rs)}) else jdbc.query(sql,{rs,_->boardRow(rs)},userId.value);val children=rows.groupBy{it.parentId};return rows.filter{it.parentId==null}.map{it.copy(children=children[it.id].orEmpty())}}
 override fun findBoardBySlug(slug:String,userId:PublicId?):ForumBoard?{val sql=boardSql("b.slug = ?",userId!=null);val rows=if(userId==null)jdbc.query(sql,{rs,_->boardRow(rs)},slug) else jdbc.query(sql,{rs,_->boardRow(rs)},slug,userId.value);return rows.firstOrNull()}
 override fun findBoardById(id:String):ForumBoard?=jdbc.query("SELECT id,slug,name,description,icon,announcement,parent_id FROM forum_board WHERE id=?",{rs,_->ForumBoard(rs.getString("id"),rs.getString("slug"),rs.getString("name"),rs.getString("description"),rs.getString("icon"),rs.getString("announcement"),rs.getString("parent_id"),0,0,false)},id).firstOrNull()
 override fun listThreads(sort:String,boardId:String?,userId:PublicId?,limit:Int,offset:Int):List<ForumThread>{val order=when(sort){"hot"->"(SELECT count(*) FROM content_interaction i WHERE i.content_id=ft.id AND i.type='LIKE')*3+(SELECT count(*) FROM content_comment c WHERE c.content_id=ft.id)*2 DESC,ft.last_reply_at DESC,ft.id DESC";"elite"->"ft.elite DESC,ft.last_reply_at DESC,ft.id DESC";else->"ft.pinned DESC,ft.last_reply_at DESC,ft.id DESC"};val where=if(boardId==null)"" else "WHERE ft.board_id=?";val args:Array<Any> = if(boardId==null)arrayOf(limit,offset)else arrayOf(boardId,limit,offset);return jdbc.query("SELECT ft.id,ft.board_id,ft.title,ft.pinned,ft.elite,ft.locked,ft.created_at,ft.last_reply_at,c.text,a.source_author_id author_id,a.username,COALESCE(a.display_name,a.username) nickname FROM forum_thread ft JOIN content c ON c.id=ft.content_id JOIN author a ON a.id=c.author_id $where ORDER BY $order LIMIT ? OFFSET ?",{rs,_->mapThread(rs,userId)},*args)}
 override fun searchThreads(query:String,limit:Int):List<ForumThread>{
  require(limit in 1..100)
  val pattern="%"+query.trim()+"%"
  return jdbc.query(
   "SELECT ft.id,ft.board_id,ft.title,ft.pinned,ft.elite,ft.locked,ft.created_at,ft.last_reply_at,c.text,a.source_author_id author_id,a.username,COALESCE(a.display_name,a.username) nickname FROM forum_thread ft JOIN content c ON c.id=ft.content_id JOIN author a ON a.id=c.author_id WHERE c.status='ACTIVE' AND c.visibility='PUBLIC' AND (ft.title ILIKE ? OR c.text ILIKE ?) ORDER BY ft.pinned DESC,ft.last_reply_at DESC,ft.id DESC LIMIT ?",
   {rs,_->mapThread(rs,null)},pattern,pattern,limit)
 }
 override fun findThread(id:PublicId,userId:PublicId?):ForumThread?=jdbc.query("SELECT ft.id,ft.board_id,ft.title,ft.pinned,ft.elite,ft.locked,ft.created_at,ft.last_reply_at,c.text,a.source_author_id author_id,a.username,COALESCE(a.display_name,a.username) nickname FROM forum_thread ft JOIN content c ON c.id=ft.content_id JOIN author a ON a.id=c.author_id WHERE ft.id=?",{rs,_->mapThread(rs,userId)},id.value).firstOrNull()
 override fun saveThread(id:PublicId,boardId:String,title:String,now:Long):ForumThread{jdbc.update("INSERT INTO forum_thread(id,board_id,content_id,title,created_at,updated_at,last_reply_at) VALUES(?,?,?,?,?,?,?)",id.value,boardId,id.value,title.trim(),now,now,now);return findThread(id,null)!!}
 override fun updateTitle(id:PublicId,title:String)=jdbc.update("UPDATE forum_thread SET title=?,updated_at=? WHERE id=?",title.trim(),System.currentTimeMillis(),id.value)>0
 override fun deleteThread(id:PublicId)=jdbc.update("DELETE FROM forum_thread WHERE id=?",id.value)>0
 override fun toggleBoardFollow(boardId:String,userId:PublicId):Boolean{val n=jdbc.queryForObject("SELECT count(*) FROM forum_board_follow WHERE board_id=? AND user_id=?",Long::class.java,boardId,userId.value)?:0;if(n>0){jdbc.update("DELETE FROM forum_board_follow WHERE board_id=? AND user_id=?",boardId,userId.value);return false};jdbc.update("INSERT INTO forum_board_follow(board_id,user_id,created_at) VALUES(?,?,?)",boardId,userId.value,System.currentTimeMillis());return true}
 override fun toggleThreadSubscribe(threadId:PublicId,userId:PublicId):Boolean{val n=jdbc.queryForObject("SELECT count(*) FROM forum_thread_subscribe WHERE thread_id=? AND user_id=?",Long::class.java,threadId.value,userId.value)?:0;if(n>0){jdbc.update("DELETE FROM forum_thread_subscribe WHERE thread_id=? AND user_id=?",threadId.value,userId.value);return false};jdbc.update("INSERT INTO forum_thread_subscribe(thread_id,user_id,created_at) VALUES(?,?,?)",threadId.value,userId.value,System.currentTimeMillis());return true}
 override fun moderate(id:PublicId,action:String):ForumThread?{val col=when(action){"pin"->"pinned";"elite"->"elite";"lock"->"locked";else->return findThread(id,null)};jdbc.update("UPDATE forum_thread SET $col=NOT $col,updated_at=? WHERE id=?",System.currentTimeMillis(),id.value);return findThread(id,null)}
 private fun mapThread(rs:java.sql.ResultSet,userId:PublicId?):ForumThread{val id=rs.getString("id");val b=findBoardById(rs.getString("board_id"))!!;val a=ForumAuthor(rs.getString("author_id"),rs.getString("username"),rs.getString("nickname"));val replies=jdbc.queryForObject("SELECT count(*) FROM content_comment WHERE content_id=?",Long::class.java,id)?:0;val likes=jdbc.queryForObject("SELECT count(*) FROM content_interaction WHERE content_id=? AND type='LIKE'",Long::class.java,id)?:0;val liked=userId!=null&&(jdbc.queryForObject("SELECT count(*) FROM content_interaction WHERE content_id=? AND user_id=? AND type='LIKE'",Long::class.java,id,userId.value)?:0)>0;val sub=userId!=null&&(jdbc.queryForObject("SELECT count(*) FROM forum_thread_subscribe WHERE thread_id=? AND user_id=?",Long::class.java,id,userId.value)?:0)>0;val media=jdbc.query("SELECT m.id,m.original_url,m.metadata->>'contentType' type FROM content_media cm JOIN media m ON m.id=cm.media_id WHERE cm.content_id=? ORDER BY cm.position",{r,_->ForumMedia(r.getString("id"),r.getString("original_url"),if(r.getString("type")?.startsWith("image/")==true)"image" else "video")},id);return ForumThread(id,b,a,rs.getString("title"),rs.getString("text")?:"",media,rs.getBoolean("pinned"),rs.getBoolean("elite"),rs.getBoolean("locked"),0,replies,likes,rs.getLong("created_at"),rs.getLong("last_reply_at"),liked,sub,false)}
 private fun boardSql(extra:String="",withFollowing:Boolean=false):String{val follow=if(withFollowing)",EXISTS (SELECT 1 FROM forum_board_follow bf2 WHERE bf2.board_id=b.id AND bf2.user_id=?) following" else ",false following";return "SELECT b.id,b.slug,b.name,b.description,b.icon,b.announcement,b.parent_id,(SELECT count(*) FROM forum_thread ft WHERE ft.board_id=b.id) thread_count,(SELECT count(*) FROM forum_board_follow bf WHERE bf.board_id=b.id) followers$follow FROM forum_board b "+if(extra.isBlank())"" else "WHERE "+extra}
 private fun boardRow(rs:java.sql.ResultSet)=ForumBoard(rs.getString("id"),rs.getString("slug"),rs.getString("name"),rs.getString("description"),rs.getString("icon"),rs.getString("announcement"),rs.getString("parent_id"),rs.getLong("thread_count"),rs.getLong("followers"),rs.getBoolean("following"))
}